package com.pizza.api;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;

/** Proves the authorization rules actually hold at the HTTP layer. */
@SpringBootTest
@AutoConfigureMockMvc
@Transactional
@DisplayName("API security")
class ApiSecurityIntegrationTest {

    @Autowired
    private MockMvc mockMvc;

    // Constructed rather than @Autowired: Spring Boot 4 does not expose a plain ObjectMapper
    // bean in this context, and the test only needs to pluck one field out of a response.
    private final ObjectMapper objectMapper = new ObjectMapper();

    private String tokenFor(String email, String password) throws Exception {
        String body = mockMvc.perform(post("/api/auth/login")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"email":"%s","password":"%s"}"""
                                .formatted(email, password)))
                .andExpect(status().isOk())
                .andReturn()
                .getResponse()
                .getContentAsString();
        return objectMapper.readTree(body).get("token").asText();
    }

    @Test
    @DisplayName("the menu is public")
    void menuIsPublic() throws Exception {
        mockMvc.perform(get("/api/products")).andExpect(status().isOk());
        mockMvc.perform(get("/api/toppings")).andExpect(status().isOk());
        mockMvc.perform(get("/api/crusts")).andExpect(status().isOk());
    }

    @Test
    @DisplayName("admin endpoints are closed without a token")
    void adminRequiresToken() throws Exception {
        mockMvc.perform(get("/api/admin/products")).andExpect(status().isForbidden());
        mockMvc.perform(get("/api/admin/orders")).andExpect(status().isForbidden());
        mockMvc.perform(get("/api/admin/reports/dashboard")).andExpect(status().isForbidden());
    }

    @Test

// ---- cart ----------------------------------------------------------
// Public, like guest checkout — you do not need an account to fill a
// basket. The cart's unguessable UUID is what protects it.
.requestMatchers("/api/carts", "/api/carts/**")
.permitAll()

// ---- orders --------------------------------------------------------
// Specific first: order history needs a real account.
.requestMatchers(HttpMethod.GET, "/api/orders/mine")
.authenticated()
// Placing an order must NOT require a login — this is guest checkout.
.requestMatchers(HttpMethod.POST, "/api/orders")
.permitAll()
// Reading one order is public so a guest can see their confirmation page
// without an account.
// LIMITATION: ids are sequential, so anyone could walk them. A production
// system would use an unguessable reference (UUID) or a signed link.
// Left simple here deliberately, and called out rather than hidden.
.requestMatchers(HttpMethod.GET, "/api/orders/*", "/api/orders/*/payment-status")
.permitAll()

// ---- server-rendered pages -----------------------------------------
// Same reasoning as GET /api/orders/* above: a guest with the link must be
// able to see and print their own receipt without an account. Same
// limitation too — the id is the only secret.
.requestMatchers(HttpMethod.GET, "/orders/*/receipt")
.permitAll()

// ---- admin ---------------------------------------------------------

